// 原Installed/Family属性来源适配的精确本域截面；不借今日属性或功勋倒证旧任官。
#include "resident/domains/politics/subordinate_appointments/political_subordinate_appointment_qualification.hpp"
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {int checks=0;void check(bool v,const char* why){++checks;if(!v)throw std::runtime_error(why);}}
int main(){try{
 auto catalog=std::make_shared<CommonCatalog>();catalog->actor_ids={"candidate"};catalog->actor_initial_birth.insert("candidate",-14400);FamilyCatalog family_catalog;IdentityPrototype prototype;prototype.attributes={50,51,52,53,54};family_catalog.prototypes.insert("candidate",prototype);FamilyState family;CommonState seed;seed.identity.tick=5;seed.next_instance_id=100;ActorRecord actor;actor.id="candidate";actor.attributes=prototype.attributes;seed.actors.insert(actor.id,actor);CommonStore c(seed,catalog);PoliticalSubordinateAppointmentState state;PoliticalSubordinateAppointmentOffer o;o.id="political_subordinate_offer:10";o.candidate_actor_id="candidate";o.tick=5;state.offers.insert(o.id,o);c.state().facts.insert(o.id,{o.id,"political_subordinate_appointment_offered",political_subordinate_appointment_module});PoliticalSubordinateQualificationAccess read(c,state,{*catalog,family_catalog,family,nullptr});auto result=read.subordinate_office_qualification_before("candidate",5,o.id);check(result.ok&&result.value.administration==50&&!result.value.merit_history_complete&&result.value.merit==0,"original administration with explicit nonnegative merit lower bound");c.state().actors.find("candidate")->merit=500;check(read.subordinate_office_qualification_before("candidate",5,o.id).value.merit==0,"today merit never becomes historic positive qualification");check(!read.subordinate_office_qualification_before("candidate",4,o.id).ok,"payload tick is mandatory");check(!read.subordinate_office_qualification_before("other",5,o.id).ok,"payload exact candidate is mandatory");state.offers.find(o.id)->candidate_actor_id="other";check(!read.subordinate_office_qualification_before("candidate",5,o.id).ok,"header alone is not qualification permission");state.offers.find(o.id)->candidate_actor_id="candidate";c.state().actors.find("candidate")->attributes.administration=60;check(!read.subordinate_office_qualification_before("candidate",5,o.id).ok,"unproven later administrative gain rejected");c.state().actors.find("candidate")->attributes=prototype.attributes;
 PoliticalSubordinateAppointmentAnswer a;a.id="political_subordinate_answer:11";a.actor_id="candidate";a.tick=5;a.accepted=false;state.answers.insert(a.id,a);c.state().facts.insert(a.id,{a.id,"political_subordinate_appointment_declined",political_subordinate_appointment_module});check(!read.subordinate_office_qualification_before("candidate",5,a.id).ok,"refusal cannot act as acceptance qualification boundary");state.answers.find(a.id)->accepted=true;c.state().facts.find(a.id)->kind="political_subordinate_appointment_accepted";check(read.subordinate_office_qualification_before("candidate",5,a.id).ok,"actual accepted payload selects its own exact boundary");c.state().facts.find(a.id)->domain="politics";check(!read.subordinate_office_qualification_before("candidate",5,a.id).ok,"old politics header cannot masquerade as new qualification boundary");
 std::cout<<checks<<" qualification adapter checks; source fixture only\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
